public class Compiler_initOptions_TriageGen1Test {

    private Compiler compiler;
    private CompilerOptions options;

    @Before
    public void setUp() {
        compiler = new Compiler();
        options = new CompilerOptions();
    }

    @Test
    public void testInitOptions_DefaultErrorManagerAndNoOutputStream() {
        // Case: errorManager is null and outStream is null (default)
        compiler.initOptions(options);

        assertNotNull(compiler.getErrorManager());
        assertThat(compiler.getErrorManager() instanceof LoggerErrorManager).isTrue();
    }

    @Test
    public void testInitOptions_WithExistingErrorManager() {
        // Case: errorManager is already set, should not be overwritten
        ErrorManager mockErrorManager = new LoggerErrorManager(new MessageFormatter(), null);
        compiler.setErrorManager(mockErrorManager);

        compiler.initOptions(options);
        assertThat(compiler.getErrorManager()).isEqualTo(mockErrorManager);
    }

    @Test
    public void testInitOptions_WithOutputStream() {
        // Case: errorManager is null but outStream is provided
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(out);

        // We need a way to inject outStream. Since it's likely a field in the class,
        // and the constructor provided is Compiler(PrintStream stream), we use that.
        compiler = new Compiler(ps);

        compiler.initOptions(options);

        assertNotNull(compiler.getErrorManager());
        assertThat(compiler.getErrorManager() instanceof PrintStreamErrorManager).isTrue();
    }

    @Test
    public void testInitOptions_DiagnosticGroupsEnablesCheckTypes() {
        // Case: options.enables(DiagnosticGroups.CHECK_TYPES) is true
        options.setCheckTypes(false);
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF);
        // Force enable via DiagnosticGroups
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.NORMAL);

        compiler.initOptions(options);

        assertThat(options.checkTypes).isTrue();
    }

    @Test
    public void testInitOptions_DiagnosticGroupsDisablesCheckTypes() {
        // Case: options.disables(DiagnosticGroups.CHECK_TYPES) is true
        options.setCheckTypes(true);
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF);

        compiler.initOptions(options);

        assertThat(options.checkTypes).isFalse();
    }

    @Test
    public void testInitOptions_DiagnosticGroupsNoOverrideAndCheckTypesFalse() {
        // Case: No override, and checkTypes is false
        // This should trigger the setWarningLevel for TYPE_PARSE_ERROR
        options.checkTypes = false;
        // Ensure no diagnostic group setting
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF); 
        // Note: The logic is: if (!options.enables && !options.disables && !options.checkTypes)
        // To hit the branch, we need to ensure the 'enables' and 'disables' checks return false.
        // In Rhino, if level is OFF, it might count as disables. 
        // We assume the logic follows the provided snippet.

        compiler.initOptions(options);

        // We verify via side effect if possible, or simply that it executes without error.
        // In a real environment, we'd check the warning level of RhinoErrorReporter.TYPE_PARSE_ERROR
    }

    @Test
    public void testInitOptions_CheckGlobalThisLevelEnabled() {
        // Case: options.checkGlobalThisLevel.isOn() is true
        options.checkGlobalThisLevel = CheckLevel.NORMAL;

        compiler.initOptions(options);

        assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.NORMAL);
    }

    @Test
    public void testInitOptions_CheckGlobalThisLevelDisabled() {
        // Case: options.checkGlobalThisLevel.isOn() is false
        options.checkGlobalThisLevel = CheckLevel.OFF;

        compiler.initOptions(options);

        // Should not change the level if it's already OFF or if logic skips
        assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.OFF);
    }

    @Test
    public void testInitOptions_CheckSymbolsTrue() {
        // Case: options.checkSymbols is true
        options.checkSymbols = true;

        compiler.initOptions(options);

        // If checkSymbols is true, the DiagnosticGroupWarningsGuard for CHECK_VARIABLES should NOT be added
        // The warningsGuard is private, so we rely on the fact that this path is covered.
    }

    @Test
    public void testInitOptions_CheckSymbolsFalseAndWarningsGuardEnabled() {
        // Case: options.checkSymbols is false AND warningsGuard does NOT disable CHECK_VARIABLES
        options.checkSymbols = false;

        compiler.initOptions(options);

        // This should add the DiagnosticGroupWarningsGuard(DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF)
    }

    @Test
    public void testInitOptions_CheckSymbolsFalseAndWarningsGuardDisablesCheckVariables() {
        // Case: options.checkSymbols is false AND warningsGuard DOES disable CHECK_VARIABLES
        options.checkSymbols = false;
        options.setWarningLevel(DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF);

        compiler.initOptions(options);

        // Should not add the extra guard
    }
}
